from html import escape
from pathlib import Path

NFL='https://media.nfl.com/content/dam/communications/football-communications/2026/news/05%2014%2026%20-%20Schedule%20Release.pdf'
NIST='https://www.nist.gov/system/files/documents/2021/07/19/ir_7346_appendix_e.pdf'
OPS='https://operations.nfl.com/inside-football-ops/players-legends/player-health-safety'
GH='https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages'
SOURCES={'NFL schedule':NFL,'NFL player health':OPS,'NIST overfitting':NIST,'GitHub Pages':GH}
nav=[('Overview','index.html'),('Strategies','strategies.html'),('Validation','validation.html'),('Data & correlation','data.html'),('Leaderboard','leaderboard.html'),('Flagged for review','flags.html')]
def table(headers,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+ '<th>Source / context</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in cells)+f'<td><a href="{url}">{escape(label)} ↗</a></td></tr>' for cells,label,url in rows)+'</tbody></table></div>'
def page(name,kicker,title,intro,body):
    links=''.join(f'<a {"aria-current=page" if file==name else ""} href="{file}">{label}</a>' for label,file in nav)
    Path(name).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | NFL Signal Lab</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap top"><a class="brand" href="index.html"><span>◆</span> NFL <b>Signal Lab</b></a><span class="tag">RESEARCH DASHBOARD</span></div></header><div class="wrap layout"><nav aria-label="Main navigation"><div class="navlabel">WORKSPACE</div>{links}</nav><main><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="intro">{intro}</p>{body}<footer>Research only · No betting advice · Sources linked in every table row</footer></main></div></body></html>''')

page('index.html','EXECUTIVE SUMMARY','Make the signal earn its place','An evidence-first framework for originating NFL lines, evaluating combinations, and separating repeatable skill from short-term results.', '''<div class="notice"><strong>Research stage, not a live betting system.</strong> No odds feed, historical dataset, model runs, validated correlations, or actual leaderboard results were available in this repository. No strategy has passed the gates.</div><div class="cards"><div><small>STRATEGIES</small><strong>3</strong><span>proposals, not validated</span></div><div><small>PASSED GATES</small><strong>0</strong><span>no tests executed</span></div><div><small>MEASURED CORRELATIONS</small><strong>—</strong><span>data not available</span></div></div><h2>Decision brief</h2><p>Start with singles and a probability forecast, then evaluate parlays and player combinations only when joint outcomes can be measured. A profitable-looking backtest alone is not evidence of skill. Luck cannot be eliminated; uncertainty, leakage, selection bias and dependence must be measured.</p>'''+table(['Finding','Status'],[(['The 2026 regular season has 272 games over 18 weeks; each team plays 17.','Verified from the NFL schedule release'],'NFL schedule',NFL),(['No source-backed prices or results were supplied; no edge or reward is established.','Unverified / not evaluated'],'NFL schedule',NFL),(['Overfitting can arise when a model fits noise in a limited sample.','Methodological context; not evidence of a particular NFL edge'],'NIST overfitting',NIST)])+'''<h2>Start here</h2><div class="actions"><a href="strategies.html">Explore strategy proposals →</a><a href="validation.html">Review the gates →</a><a href="flags.html">See open issues →</a></div>''')
page('strategies.html','RESEARCH / 01','Strategy proposals','These are testable designs, not verified edges, predictions, or recommendations. Source links provide context, not proof of profitability.',table(['Strategy','Candidate signal & line construction','Key failure mode','Status'],[(['Single game line','Fit pregame team-strength and availability features; forecast a score-margin distribution. Convert its median to a fair spread and derive win probabilities.','Leakage, stale availability, price and rule mismatch.','Proposed'],'NFL player health',OPS),(['Game parlay','Forecast joint game outcomes; estimate conditional dependence and compare the joint probability with the actual quoted payout.','Multiplying marginal probabilities assumes independence; selection and void rules matter.','Proposed'],'NIST overfitting',NIST),(['Player prop combinations','Model opportunity and efficiency jointly, including shared game context; simulate player outcomes and apply exact settlement rules.','Sparse combinations, player inactivity and shared volume.','Proposed'],'NFL player health',OPS)])+'''<h2>Pricing protocol</h2><p>For decimal odds D and a binary wager with no push or void, the break-even probability is 1/D and expected net return per unit is p × D − 1. For American odds, convert positive A to 1 + A/100 and negative A to 1 + 100/|A|. Pushes, voids, limits, fees and actual attainable prices require explicit settlement modeling. Market implied probability includes margin and is not automatically a fair probability.</p><p>Proposed research formulae; not observed market prices. Same-game parlays require the operator’s actual quote and eligibility rules, not a product of individual odds.</p>''')
page('validation.html','RESEARCH / 02','Validation gates','A preregistered, chronological evaluation is required before a strategy can appear as eligible on the leaderboard.',table(['Gate','Proposed pass requirement','Evidence required'],[(['1 · Provenance','Document source, retrieval time, terms, timestamp and point-in-time availability; reconcile outcomes and settlement against authoritative records.','Immutable snapshots and row-level links.'],'NFL schedule',NFL),(['2 · Leakage','Freeze features before the forecast cutoff. Use rolling training windows and an untouched later test period.','Timestamp audit and reproducible split manifest.'],'NIST overfitting',NIST),(['3 · Forecast quality','Evaluate log loss, Brier score and calibration versus a preregistered baseline; include uncertainty and sample sizes.','Out-of-sample forecasts, outcomes and baseline.'],'NIST overfitting',NIST),(['4 · Economics','Test timestamped executable prices and full settlement, including pushes and voids; require a prespecified positive lower confidence bound on net return.','Price snapshots, terms, ledger and game-clustered intervals.'],'NIST overfitting',NIST),(['5 · Robustness','Prespecify minimum sample size, multiplicity adjustment, season and regime checks, and stress tests before seeing test results.','Experiment registry and sensitivity report.'],'NIST overfitting',NIST)])+'''<div class="notice"><strong>No gate passed.</strong> Thresholds, reward budget and significance procedure must be preregistered; none are represented as validated. Results can remain inconclusive even after all data are collected.</div><h2>Reducing luck, not removing it</h2><p>Use proper probability scores, game-level resampling, confidence intervals and repeated forward tests. Correct for the number of strategies tried and disclose every trial, including failures. These steps reduce false discoveries; they cannot prove that luck is absent or guarantee future performance.</p>''')
page('data.html','RESEARCH / 03','Data & correlation','A defensible pipeline needs official, point-in-time inputs and auditable settlement. No empirical correlation values are currently available.',table(['Input','Use','Availability / status'],[(['Schedule and game IDs','Join games and assign chronological splits.','2026 structure verified; game-level dataset not ingested.'],'NFL schedule',NFL),(['Player status','Potential availability feature, strictly as known at cutoff.','No archived point-in-time records ingested.'],'NFL player health',OPS),(['Odds and settlement','Compare probabilities with executable prices and evaluate realized returns.','No official sportsbook snapshots or settlement terms available; unverified.'],'NFL schedule',NFL),(['Model inputs and outcomes','Construct features and reconcile final outcomes to official records.','No row-level game or prop data ingested.'],'NFL schedule',NFL)])+'''<h2>Correlation register</h2>'''+table(['Pair','Estimate','Sample / interval','Status'],[(['Game outcome ↔ game outcome','','','Unverified: no paired observations.'],'NFL schedule',NFL),(['Player prop ↔ player prop','','','Unverified: no paired observations.'],'NFL player health',OPS),(['Game outcome ↔ player prop','','','Unverified: no paired observations.'],'NFL schedule',NFL)])+'''<p>Once eligible data exist, define the variables and cutoff first, calculate a suitable dependence statistic on paired observations, report sample sizes and game-clustered uncertainty, and separately estimate joint event probabilities. Correlation is not itself a joint probability, nor a causal claim. A blank is not zero.</p>''')
page('leaderboard.html','COMPETITION / 04','Leaderboard','A proposed, reward-oriented competition. The board intentionally contains no performance rankings because there are no validated submissions.',table(['Entry','Gate status','Score','Reward'],[(['Single game line','Not evaluated','',''],'NIST overfitting',NIST),(['Game parlay','Not evaluated','',''],'NIST overfitting',NIST),(['Player prop combinations','Not evaluated','',''],'NIST overfitting',NIST)])+'''<h2>Proposed rules</h2><p>Rank only gate-passing submissions by a preregistered out-of-sample proper scoring rule relative to the same baseline and horizon. Publish uncertainty, sample count and economic results separately; do not rank by raw win rate or short-run return alone. Use a locked submission cutoff, identical data availability, full trial registry and an untouched final evaluation. No reward amount, sponsor or award exists yet; prize eligibility and tie rules require a published competition charter.</p>''')
page('flags.html','REVIEW / 05','Flagged for review','Open limitations are visible by design and do not imply that a missing value is zero.',table(['Issue','Impact','Next evidence needed'],[(['Historical official odds, archived executable quotes and operator terms absent','No edge, ROI or bet can be verified.','Time-stamped source records and settlement rules.'],'NFL schedule',NFL),(['Official outcomes, player props and point-in-time availability not ingested','No backtests or player estimates.','Licensed or official data and reproducible reconciliation.'],'NFL player health',OPS),(['No joint sample or model fitted','Correlation and parlay probabilities remain blank.','Paired outcomes and uncertainty estimates.'],'NIST overfitting',NIST),(['No competition or reward funding exists','Leaderboard and rewards are proposals only.','Competition charter and funding.'],'GitHub Pages',GH),(['NFL schedule is a primary source for season structure, not an official odds source','Links in missing-data rows are context, not confirmation of unavailable values.','Official operator source for each quote and rule.'],'NFL schedule',NFL)])+'''<h2>Verification boundary</h2><p>Only the explicitly stated NFL schedule fact is presented as a verified sports fact. Proposed formulas and procedures are research designs, not externally verified performance results. External links are supplied for manual review; link accessibility can vary by network and region.</p>''')
